     1→import { useState } from "react";
     2→import { useQuery } from "@tanstack/react-query";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import { useAuth } from "@/hooks/useAuth";
     5→import {
     6→  Dialog,
     7→  DialogContent,
     8→  DialogDescription,
     9→  DialogHeader,
    10→  DialogTitle,
    11→  DialogTrigger,
    12→} from "@/components/ui/dialog";
    13→import {
    14→  AlertDialog,
    15→  AlertDialogAction,
    16→  AlertDialogCancel,
    17→  AlertDialogContent,
    18→  AlertDialogDescription,
    19→  AlertDialogFooter,
    20→  AlertDialogHeader,
    21→  AlertDialogTitle,
    22→} from "@/components/ui/alert-dialog";
    23→import { Button } from "@/components/ui/button";
    24→import { Badge } from "@/components/ui/badge";
    25→import { toast } from "sonner";
    26→import { Crown, Loader2, Sparkles, Zap, Check, ArrowRight, ArrowDown, CalendarClock, XCircle } from "lucide-react";
    27→import { format } from "date-fns";
    28→
    29→interface SubscriptionDialogProps {
    30→  trigger?: React.ReactNode;
    31→}
    32→
    33→const SubscriptionDialog = ({ trigger }: SubscriptionDialogProps) => {
    34→  const { user, profile, refreshProfile } = useAuth();
    35→  const [open, setOpen] = useState(false);
    36→  const [buying, setBuying] = useState<string | null>(null);
    37→  const [cancelling, setCancelling] = useState(false);
    38→  const [confirmAction, setConfirmAction] = useState<{
    39→    type: "upgrade" | "downgrade" | "cancel_subscription";
    40→    planId?: string;
    41→    planName?: string;
    42→    price?: number;
    43→  } | null>(null);
    44→  const [downgrading, setDowngrading] = useState(false);
    45→
    46→  const currentPlan = profile?.plan ?? "free";
    47→  const isPaid = currentPlan !== "free";
    48→  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
    49→    ? new Date((profile as any).subscription_ends_at)
    50→    : null;
    51→  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
    52→  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;
    53→
    54→  const { data: plans } = useQuery({
    55→    queryKey: ["subscription_plans_active"],
    56→    queryFn: async () => {
    57→      const { data, error } = await supabase
    58→        .from("plans")
    59→        .select("*")
    60→        .eq("active", true)
    61→        .order("price");
    62→      if (error) throw error;
    63→      return data;
    64→    },
    65→  });
    66→
    67→  const { data: config } = useQuery({
    68→    queryKey: ["platform_config_payg"],
    69→    queryFn: async () => {
    70→      const { data, error } = await supabase
    71→        .from("platform_config")
    72→        .select("*")
    73→        .limit(1)
    74→        .single();
    75→      if (error) return null;
    76→      return data;
    77→    },
    78→  });
    79→
    80→  const paygCost = (config as any)?.payg_per_resume_cost ?? 0.07;
    81→
    82→  const handleSubscribe = async (planId: string) => {
    83→    if (!user) return;
    84→    setBuying(planId);
    85→
    86→    try {
    87→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
    88→        body: {
    89→          plan_id: planId,
    90→          return_url: `${window.location.origin}/payment/callback`,
    91→        },
    92→      });
    93→
    94→      if (error) throw error;
    95→
    96→      if (!data?.checkout_url) {
    97→        toast.error(data?.error || "Failed to create checkout session");
    98→        return;
    99→      }
   100→
   101→      // Redirect to Dodo hosted checkout
   102→      window.location.href = data.checkout_url;
   103→    } catch (err: any) {
   104→      toast.error(err.message);
   105→    } finally {
   106→      setBuying(null);
   107→    }
   108→  };
   109→
   110→  const handleCancelSubscription = async () => {
   111→    setCancelling(true);
   112→    try {
   113→      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
   114→      if (error) throw error;
   115→      toast.success("Subscription will cancel at the end of your current billing period.");
   116→      await refreshProfile();
   117→      setConfirmAction(null);
   118→    } catch (err: any) {
   119→      toast.error("Failed to cancel: " + err.message);
   120→    } finally {
   121→      setCancelling(false);
   122→    }
   123→  };
   124→
   125→  const handleDowngradeToPayg = async () => {
   126→    setDowngrading(true);
   127→    try {
   128→      if (hasActiveSubscription) {
   129→        const { error: cancelError } = await supabase.functions.invoke("cancel-dodo-subscription", {});
   130→        if (cancelError) console.error("Failed to cancel subscription:", cancelError);
   131→      }
   132→      const { error } = await supabase
   133→        .from("profiles")
   134→        .update({ plan: "free", subscription_ends_at: null, dodo_subscription_id: null } as any)
   135→        .eq("user_id", user?.id);
   136→      if (error) throw error;
   137→      toast.success("Switched to Pay As You Go. Your remaining credits are preserved.");
   138→      await refreshProfile();
   139→      setConfirmAction(null);
   140→    } catch (err: any) {
   141→      toast.error("Failed to downgrade: " + err.message);
   142→    } finally {
   143→      setDowngrading(false);
   144→    }
   145→  };
   146→
   147→  const handleConfirmedAction = () => {
   148→    if (!confirmAction) return;
   149→    if (confirmAction.type === "upgrade" && confirmAction.planId) {
   150→      handleSubscribe(confirmAction.planId);
   151→      setConfirmAction(null);
   152→    } else if (confirmAction.type === "downgrade") {
   153→      handleDowngradeToPayg();
   154→    } else if (confirmAction.type === "cancel_subscription") {
   155→      handleCancelSubscription();
   156→    }
   157→  };
   158→
   159→  return (
   160→    <>
   161→      <Dialog open={open} onOpenChange={setOpen}>
   162→        <DialogTrigger asChild>
   163→          {trigger || (
   164→            <Button variant="outline" size="sm" className="gap-1.5">
   165→              <Crown className="h-3.5 w-3.5" />
   166→              Upgrade Plan
   167→            </Button>
   168→          )}
   169→        </DialogTrigger>
   170→        <DialogContent className="sm:max-w-lg">
   171→          <DialogHeader>
   172→            <DialogTitle className="flex items-center gap-2">
   173→              <Sparkles className="h-5 w-5 text-primary" />
   174→              Choose Your Plan
   175→            </DialogTitle>
   176→            <DialogDescription>
   177→              {isPaid
   178→                ? "Manage your subscription or switch plans."
   179→                : "Upgrade to save on every resume ranked. All plans auto-renew."}
   180→            </DialogDescription>
   181→          </DialogHeader>
   182→
   183→          {/* Current Plan Banner */}
   184→          <div className="rounded-lg border border-border bg-muted/50 px-4 py-3 flex items-center gap-3">
   185→            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15">
   186→              {isPaid ? <Crown className="h-4 w-4 text-primary" /> : <Zap className="h-4 w-4 text-primary" />}
   187→            </div>
   188→            <div className="flex-1">
   189→              <p className="text-sm font-medium text-foreground">
   190→                Current: {isPaid ? currentPlan : "Pay As You Go"}
   191→              </p>
   192→              <p className="text-xs text-muted-foreground">
   193→                {isPaid
   194→                  ? subscriptionEndsAt
   195→                    ? isExpired
   196→                      ? "Your subscription has expired"
   197→                      : hasActiveSubscription
   198→                        ? `Auto-renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
   199→                        : `Expires ${format(subscriptionEndsAt, "MMM d, yyyy")}`
   200→                    : "You're saving on every resume!"
   201→                  : `$${paygCost}/resume • Upgrade to save more`}
   202→              </p>
   203→            </div>
   204→            {isPaid && subscriptionEndsAt && !isExpired && (
   205→              <Badge variant="secondary" className="text-xs gap-1">
   206→                <CalendarClock className="h-3 w-3" />
   207→                {format(subscriptionEndsAt, "MMM d")}
   208→              </Badge>
   209→            )}
   210→            {isPaid && isExpired && (
   211→              <Badge variant="destructive" className="text-xs">Expired</Badge>
   212→            )}
   213→            {!isPaid && (
   214→              <Badge variant="secondary" className="text-xs">Active</Badge>
   215→            )}
   216→          </div>
   217→
   218→          {/* Cancel Subscription Button */}
   219→          {isPaid && hasActiveSubscription && !isExpired && (
   220→            <Button
   221→              variant="outline"
   222→              size="sm"
   223→              className="gap-1.5 text-xs border-destructive/30 text-destructive hover:bg-destructive/10"
   224→              onClick={() => setConfirmAction({ type: "cancel_subscription" })}
   225→              disabled={cancelling}
   226→            >
   227→              {cancelling ? <Loader2 className="h-3 w-3 animate-spin" /> : <XCircle className="h-3 w-3" />}
   228→              Cancel Auto-Renewal
   229→            </Button>
   230→          )}
   231→
   232→          {/* PAYG Card */}
   233→          <div className={`rounded-lg border p-4 ${!isPaid ? "border-primary/50 bg-primary/5" : "border-border"}`}>
   234→            <div className="flex items-center justify-between">
   235→              <div>
   236→                <div className="flex items-center gap-2">
   237→                  <p className="font-semibold text-foreground">Pay As You Go</p>
   238→                  {!isPaid && <Badge variant="default" className="text-[10px] px-1.5 py-0">Current</Badge>}
   239→                </div>
   240→                <p className="text-xs text-muted-foreground mt-1">No commitment • Buy credits anytime</p>
   241→              </div>
   242→              <div className="flex items-center gap-3">
   243→                <div className="text-right">
   244→                  <p className="text-lg font-bold text-foreground">$0</p>
   245→                  <p className="text-xs text-muted-foreground">/month</p>
   246→                </div>
   247→                {isPaid && (
   248→                  <Button
   249→                    variant="outline"
   250→                    size="sm"
   251→                    className="gap-1 h-8 text-xs border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
   252→                    onClick={() => setConfirmAction({ type: "downgrade" })}
   253→                  >
   254→                    <ArrowDown className="h-3 w-3" />
   255→                    Switch
   256→                  </Button>
   257→                )}
   258→              </div>
   259→            </div>
   260→            <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
   261→              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${paygCost}/resume</span>
   262→              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
   263→            </div>
   264→          </div>
   265→
   266→          {/* Subscription Plans */}
   267→          <div className="space-y-3">
   268→            {plans?.map((plan: any, idx: number) => {
   269→              const isCurrentPlan = currentPlan === plan.name;
   270→              const savings = paygCost > 0 ? Math.round(((paygCost - (plan.per_resume_cost ?? 0.05)) / paygCost) * 100) : 0;
   271→              const isPopular = idx === Math.floor((plans.length - 1) / 2);
   272→
   273→              return (
   274→                <div
   275→                  key={plan.id}
   276→                  className={`relative rounded-lg border p-4 transition-colors ${
   277→                    isCurrentPlan
   278→                      ? "border-primary/50 bg-primary/5"
   279→                      : "border-border hover:border-primary/30 hover:bg-accent/30"
   280→                  }`}
   281→                >
   282→                  {isPopular && !isCurrentPlan && (
   283→                    <Badge className="absolute -top-2.5 right-3 bg-primary text-primary-foreground text-[10px] px-2 py-0.5">
   284→                      Popular
   285→                    </Badge>
   286→                  )}
   287→                  <div className="flex items-center justify-between">
   288→                    <div>
   289→                      <div className="flex items-center gap-2">
   290→                        <p className="font-semibold text-foreground">{plan.name}</p>
   291→                        {isCurrentPlan && <Badge variant="default" className="text-[10px] px-1.5 py-0">Current</Badge>}
   292→                        {savings > 0 && !isCurrentPlan && (
   293→                          <Badge variant="secondary" className="text-[10px] px-1.5 py-0 text-primary">
   294→                            Save {savings}%
   295→                          </Badge>
   296→                        )}
   297→                      </div>
   298→                      <p className="text-xs text-muted-foreground mt-1">
   299→                        {plan.billing_type} • {plan.credits} credits • Auto-renews
   300→                      </p>
   301→                    </div>
   302→                    <div className="text-right">
   303→                      <p className="text-lg font-bold text-foreground">${plan.price}</p>
   304→                      <p className="text-xs text-muted-foreground">/{plan.billing_type === "yearly" ? "year" : "mo"}</p>
   305→                    </div>
   306→                  </div>
   307→                  <div className="mt-3 flex items-center justify-between">
   308→                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
   309→                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${plan.per_resume_cost ?? 0.05}/resume</span>
   310→                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
   311→                    </div>
   312→                    {!isCurrentPlan && (
   313→                      <Button
   314→                        size="sm"
   315→                        onClick={() =>
   316→                          setConfirmAction({
   317→                            type: "upgrade",
   318→                            planId: plan.id,
   319→                            planName: plan.name,
   320→                            price: plan.price,
   321→                          })
   322→                        }
   323→                        disabled={buying === plan.id}
   324→                        className="gap-1 h-8"
   325→                      >
   326→                        {buying === plan.id ? (
   327→                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
   328→                        ) : (
   329→                          <>
   330→                            Subscribe <ArrowRight className="h-3 w-3" />
   331→                          </>
   332→                        )}
   333→                      </Button>
   334→                    )}
   335→                  </div>
   336→                </div>
   337→              );
   338→            })}
   339→            {(!plans || plans.length === 0) && (
   340→              <p className="text-sm text-muted-foreground text-center py-4">
   341→                No subscription plans available right now.
   342→              </p>
   343→            )}
   344→          </div>
   345→
   346→          <p className="text-[11px] text-muted-foreground text-center pt-1">
   347→            All plans auto-renew. Cancel anytime before your next billing date.
   348→          </p>
   349→        </DialogContent>
   350→      </Dialog>
   351→
   352→      {/* Confirmation AlertDialog */}
   353→      <AlertDialog open={confirmAction !== null} onOpenChange={(o) => !o && setConfirmAction(null)}>
   354→        <AlertDialogContent>
   355→          <AlertDialogHeader>
   356→            <AlertDialogTitle>
   357→              {confirmAction?.type === "upgrade"
   358→                ? `Subscribe to ${confirmAction.planName}?`
   359→                : confirmAction?.type === "cancel_subscription"
   360→                  ? "Cancel Auto-Renewal?"
   361→                  : "Switch to Pay As You Go?"}
   362→            </AlertDialogTitle>
   363→            <AlertDialogDescription>
   364→              {confirmAction?.type === "upgrade" ? (
   365→                <>
   366→                  You'll be redirected to our secure checkout page to complete payment of{" "}
   367→                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
   368→                  Your subscription will auto-renew each billing period.
   369→                </>
   370→              ) : confirmAction?.type === "cancel_subscription" ? (
   371→                <>
   372→                  Your subscription will remain active until the end of your current billing period.
   373→                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
   374→                </>
   375→              ) : (
   376→                <>
   377→                  You'll switch back to Pay As You Go pricing at <span className="font-semibold text-foreground">${paygCost}/resume</span>.
   378→                  Your remaining credits will be preserved and you can still purchase credit top-ups.
   379→                  {hasActiveSubscription && " Your active subscription will also be cancelled."}
   380→                </>
   381→              )}
   382→            </AlertDialogDescription>
   383→          </AlertDialogHeader>
   384→          <AlertDialogFooter>
   385→            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
   386→            <AlertDialogAction
   387→              onClick={handleConfirmedAction}
   388→              disabled={downgrading || cancelling}
   389→              className={confirmAction?.type !== "upgrade" ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
   390→            >
   391→              {(downgrading || cancelling) && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
   392→              {confirmAction?.type === "upgrade"
   393→                ? "Proceed to Payment"
   394→                : confirmAction?.type === "cancel_subscription"
   395→                  ? "Cancel Auto-Renewal"
   396→                  : "Confirm Downgrade"}
   397→            </AlertDialogAction>
   398→          </AlertDialogFooter>
   399→        </AlertDialogContent>
   400→      </AlertDialog>
   401→    </>
   402→  );
   403→};
   404→
   405→export default SubscriptionDialog;
   406→

