     1→// @ts-nocheck
     2→// deno-lint-ignore-file no-explicit-any
     3→/// <reference lib="deno.ns" />
     4→// deno-lint-ignore-file no-explicit-any
     5→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
     6→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
     7→
     8→const corsHeaders = {
     9→  "Access-Control-Allow-Origin": "*",
    10→  "Access-Control-Allow-Headers":
    11→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
    12→};
    13→
    14→Deno.serve(async (req) => {
    15→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
    16→
    17→  try {
    18→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    19→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    20→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    21→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    22→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    23→
    24→    if (!DODO_API_KEY) {
    25→      return new Response(
    26→        JSON.stringify({ error: "Dodo Payments API key not configured" }),
    27→        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    28→      );
    29→    }
    30→
    31→    // Authenticate user
    32→    const authHeader = req.headers.get("Authorization");
    33→    if (!authHeader) {
    34→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    35→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
    36→      });
    37→    }
    38→
    39→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    40→      global: { headers: { Authorization: authHeader } },
    41→    });
    42→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    43→    if (userError || !user) {
    44→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    45→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
    46→      });
    47→    }
    48→
    49→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    50→    const body = await req.json();
    51→    const { pack_id, plan_id, return_url } = body as Record<string, unknown>;
    52→
    53→    if (!pack_id && !plan_id) {
    54→      return new Response(JSON.stringify({ error: "pack_id or plan_id required" }), {
    55→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
    56→      });
    57→    }
    58→
    59→    let productId: string;
    60→    let amount: number;
    61→    let credits: number;
    62→    let currency = "USD";
    63→    let itemName: string;
    64→    let itemType: "pack" | "plan";
    65→    let itemId: string;
    66→
    67→    if (pack_id) {
    68→      const { data: pack, error } = await supabase
    69→        .from("credit_packs")
    70→        .select("*")
    71→        .eq("id", pack_id)
    72→        .eq("active", true)
    73→        .single();
    74→      if (error || !pack) {
    75→        return new Response(JSON.stringify({ error: "Credit pack not found or inactive" }), {
    76→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
    77→        });
    78→      }
    79→      if (!pack.dodo_product_id) {
    80→        return new Response(JSON.stringify({ error: "This pack is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
    81→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
    82→        });
    83→      }
    84→      productId = pack.dodo_product_id;
    85→      amount = Math.round(pack.price * 100);
    86→      credits = pack.credits;
    87→      itemName = pack.name;
    88→      itemType = "pack";
    89→      itemId = String(pack_id);
    90→    } else {
    91→      const { data: plan, error } = await supabase
    92→        .from("plans")
    93→        .select("*")
    94→        .eq("id", plan_id)
    95→        .eq("active", true)
    96→        .single();
    97→      if (error || !plan) {
    98→        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
    99→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
   100→        });
   101→      }
   102→      if (!plan.dodo_product_id) {
   103→        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
   104→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   105→        });
   106→      }
   107→      productId = plan.dodo_product_id;
   108→      amount = Math.round(plan.price * 100);
   109→      credits = plan.credits;
   110→      itemName = plan.name;
   111→      itemType = "plan";
   112→      itemId = String(plan_id);
   113→    }
   114→
   115→    // Build return URL
   116→    const baseReturnUrl =
   117→      (typeof return_url === "string" && return_url) ||
   118→      `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;
   119→
   120→    // 1) Create local payment record first to get a stable identifier
   121→    const insertRes = await supabase
   122→      .from("payments")
   123→      .insert({
