   171→          .update({ status: "failed", dodo_payment_id: paymentId })
   172→          .eq("id", localPaymentId);
   173→      } else if (paymentId) {
   174→        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
   175→      }
   176→      await markProcessed(null);
   177→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
   178→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   179→      if (subscriptionId) {
   180→        const { data: profile } = await supabase
   181→          .from("profiles")
   182→          .select("user_id, plan, credits")
   183→          .eq("dodo_subscription_id", subscriptionId)
   184→          .single();
   185→
   186→        if (profile) {
   187→          const { data: plan } = await supabase
   188→            .from("plans")
   189→            .select("credits, billing_type")
   190→            .eq("name", profile.plan)
   191→            .single();
   192→
   193→          if (plan) {
   194→            const endsAt = new Date();
   195→            if (plan.billing_type === "yearly") {
   196→              endsAt.setFullYear(endsAt.getFullYear() + 1);
   197→            } else {
   198→              endsAt.setMonth(endsAt.getMonth() + 1);
   199→            }
   200→            await supabase
   201→              .from("profiles")
   202→              .update({
   203→                credits: profile.credits + plan.credits,
   204→                subscription_ends_at: endsAt.toISOString(),
   205→              })
   206→              .eq("user_id", profile.user_id);
   207→          }
   208→        }
   209→      }
   210→      await markProcessed(null);
   211→    } else if (
   212→      eventType === "subscription.cancelled" ||
   213→      eventType === "subscription_cancelled" ||
   214→      eventType === "subscription.on_hold" ||
   215→      eventType === "subscription.failed"
   216→    ) {
   217→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   218→      if (subscriptionId) {
   219→        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
   220→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
   221→          await supabase
   222→            .from("profiles")
   223→            .update({
   224→              plan: "free",
   225→              dodo_subscription_id: null,
   226→              subscription_ends_at: null,
   227→            })
   228→            .eq("dodo_subscription_id", subscriptionId);
   229→        }
   230→      }
   231→      await markProcessed(null);
   232→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
   233→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   234→      if (subscriptionId && localPaymentId) {
   235→        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
   236→        if (payment) {
   237→          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
   238→          await markProcessed(payment.user_id);
   239→        }
   240→      }
   241→    }
   242→
   243→    return new Response("OK", { status: 200, headers: corsHeaders });
   244→  } catch (err) {
   245→    console.error("dodo-webhook error:", err);
   246→    return new Response("Internal error", { status: 500, headers: corsHeaders });
   247→  }
