     9→type CallbackStatus = "loading" | "success" | "failed";
    10→
    11→const SUCCESS_STATUSES = new Set(["paid", "completed", "succeeded"]);
    12→const FAILED_STATUSES = new Set(["failed", "cancelled", "dismissed"]);
    13→
    14→const PaymentCallback = () => {
    15→  const [searchParams] = useSearchParams();
    16→  const navigate = useNavigate();
    17→  const { refreshProfile, user } = useAuth();
    18→  const [status, setStatus] = useState<CallbackStatus>("loading");
    19→
    20→  const statusParam = (searchParams.get("status") || searchParams.get("payment_status") || "").toLowerCase();
    21→  const urlPaymentId = searchParams.get("payment_id") || searchParams.get("paymentId");
    22→  const localPaymentId = searchParams.get("local_payment_id") || searchParams.get("localPaymentId");
    23→  const checkoutSessionId = searchParams.get("checkout_session_id") || searchParams.get("session_id");
    24→
    25→  const pollPaymentStatus = useCallback(async (maxAttempts = 10) => {
    26→    const refs = {
    27→      local: localPaymentId,
    28→      dodo: urlPaymentId,
    29→      session: checkoutSessionId,
    30→    };
    31→
    32→    for (let i = 0; i < maxAttempts; i++) {
    33→      if (refs.local) {
    34→        const { data } = await supabase
    35→          .from("payments")
    36→          .select("status")
    37→          .eq("id", refs.local)
    38→          .maybeSingle();
    39→        const current = (data?.status || "").toLowerCase();
    40→        if (SUCCESS_STATUSES.has(current)) return "success";
    41→        if (FAILED_STATUSES.has(current)) return "failed";
    42→      }
    43→
    44→      if (refs.dodo) {
    45→        const { data } = await supabase
    46→          .from("payments")
    47→          .select("status")
    48→          .eq("dodo_payment_id", refs.dodo)
    49→          .maybeSingle();
    50→        const current = (data?.status || "").toLowerCase();
    51→        if (SUCCESS_STATUSES.has(current)) return "success";
    52→        if (FAILED_STATUSES.has(current)) return "failed";
    53→      }
    54→
    55→      if (refs.session) {
    56→        const { data } = await supabase
    57→          .from("payments")
    58→          .select("status")
    59→          .eq("dodo_checkout_session_id", refs.session)
    60→          .maybeSingle();
    61→        const current = (data?.status || "").toLowerCase();
    62→        if (SUCCESS_STATUSES.has(current)) return "success";
    63→        if (FAILED_STATUSES.has(current)) return "failed";
    64→      }
    65→
    66→      await new Promise((resolve) => setTimeout(resolve, 2000));
    67→    }
    68→
    69→    return "timeout";
    70→  }, [checkoutSessionId, localPaymentId, urlPaymentId]);
    71→
    72→  const verifyWithServer = useCallback(async () => {
    73→    const { data, error } = await supabase.functions.invoke("verify-dodo-payment", {
    74→      body: {
    75→        payment_id: urlPaymentId,
    76→        local_payment_id: localPaymentId,
    77→        checkout_session_id: checkoutSessionId,
    78→      },
    79→    });
    80→
    81→    if (error) {
    82→      return null;
    83→    }
    84→
    85→    const localStatus = String(data?.local_status || "").toLowerCase();
    86→    if (SUCCESS_STATUSES.has(localStatus)) return "success";
    87→    if (FAILED_STATUSES.has(localStatus)) return "failed";
    88→    return null;
    89→  }, [checkoutSessionId, localPaymentId, urlPaymentId]);
    90→
    91→  useEffect(() => {
    92→    let cancelled = false;
    93→
    94→    const runVerification = async () => {
    95→      if (statusParam === "failed") {
    96→        if (!cancelled) setStatus("failed");
    97→        return;
    98→      }
    99→
   100→      const hasRefs = Boolean(urlPaymentId || localPaymentId || checkoutSessionId);
   101→
   102→      if (hasRefs) {
   103→        const serverResult = await verifyWithServer();
   104→        if (cancelled) return;
   105→
   106→        if (serverResult === "success") {
   107→          if (user?.id) await refreshProfile();
   108→          if (!cancelled) setStatus("success");
   109→          return;
   110→        }
   111→
   112→        if (serverResult === "failed") {
   113→          if (!cancelled) setStatus("failed");
   114→          return;
   115→        }
   116→
   117→        const polled = await pollPaymentStatus(statusParam ? 8 : 12);
   118→        if (cancelled) return;
   119→
   120→        if (polled === "success") {
   121→          if (user?.id) await refreshProfile();
   122→          if (!cancelled) setStatus("success");
   123→          return;
   124→        }
   125→
   126→        if (polled === "failed") {
   127→          if (!cancelled) setStatus("failed");
   128→          return;
   129→        }
   130→
   131→        // Polling timed out — do one final server verify (webhook may have arrived by now)
   132→        const finalCheck = await verifyWithServer();
   133→        if (cancelled) return;
   134→
   135→        if (finalCheck === "success") {
   136→          if (user?.id) await refreshProfile();
   137→          if (!cancelled) setStatus("success");
   138→          return;
   139→        }
   140→
   141→        // If Dodo redirected with success status, trust it to avoid trapping users.
   142→        if (statusParam === "succeeded" || statusParam === "success" || statusParam === "paid") {
   143→          if (user?.id) await refreshProfile();
   144→          if (!cancelled) setStatus("success");
   145→          return;
   146→        }
   147→
   148→        if (!cancelled) setStatus("failed");
   149→        return;
   150→      }
   151→
   152→      // Bare /payment/callback route with no params: don't keep spinner forever.
   153→      if (user?.id) {
   154→        await refreshProfile();
   155→      }
   156→      if (!cancelled) setStatus("success");
   157→    };
   158→
   159→    void runVerification();
   160→
   161→    return () => {
   162→      cancelled = true;
   163→    };
   164→  }, [checkoutSessionId, localPaymentId, pollPaymentStatus, statusParam, urlPaymentId, user?.id, verifyWithServer]);
   165→
   166→  useEffect(() => {
   167→    if (status === "success") {
   168→      const timer = setTimeout(() => navigate("/", { replace: true }), 4000);
   169→      return () => clearTimeout(timer);
   170→    }
   171→  }, [status, navigate]);
   172→
   173→  return (
   174→    <div className="min-h-screen flex items-center justify-center bg-background p-4">
   175→      <Card className="w-full max-w-md">
   176→        <CardContent className="pt-8 pb-8 text-center space-y-4">
   177→          {status === "loading" && (
   178→            <>
   179→              <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto" />
   180→              <h2 className="text-xl font-semibold text-foreground">Verifying payment…</h2>
   181→              <p className="text-sm text-muted-foreground">Please wait while we confirm your payment.</p>
   182→            </>
   183→          )}
   184→
   185→          {status === "success" && (
   186→            <>
   187→              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-primary/10">
   188→                <CheckCircle2 className="h-8 w-8 text-primary" />
   189→              </div>
   190→              <h2 className="text-xl font-semibold text-foreground">Payment Successful!</h2>
   191→              <p className="text-sm text-muted-foreground">Your credits have been added. Redirecting to dashboard…</p>
   192→              <Button variant="outline" onClick={() => navigate("/", { replace: true })}>
   193→                Go to Dashboard Now
   194→              </Button>
   195→            </>
   196→          )}
   197→
   198→          {status === "failed" && (
   199→            <>
   200→              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-destructive/10">
   201→                <XCircle className="h-8 w-8 text-destructive" />
   202→              </div>
   203→              <h2 className="text-xl font-semibold text-foreground">Payment Verification Failed</h2>
   204→              <p className="text-sm text-muted-foreground">We could not confirm this payment yet. Please try again in a few seconds.</p>
   205→              <Button onClick={() => navigate("/", { replace: true })}>Return to Dashboard</Button>
   206→            </>
   207→          )}
   208→        </CardContent>
   209→      </Card>
   210→    </div>
   211→  );
   212→};
   213→
   214→export default PaymentCallback;
   215→

